with ev as (
  select e.*, b.slug as base_slug from public.experiences e join public.bases b on b.id = e.base_id where e.slug = 'essencia-lua-cheia'
),
ses as (
  select s.* from public.sessions s join ev on ev.id = s.experience_id
),
checks as (
  select 'EVENTO_EM_RASCUNHO' as check_name,
